"""Validate and summarise the incident-readiness dataset.

Usage: python collect.py data.csv
Checks rows against schema.csv enums and prints summary counts.
"""
import csv
import sys
from collections import Counter
from pathlib import Path

HERE = Path(__file__).parent

ENUMS = {
    "disclosed_by": {"developer", "third_party_researcher", "journalist", "user", "regulator", "other"},
    "category": {"misuse_uplift", "dangerous_capability_eval", "security_breach",
                 "autonomy_or_deception", "harmful_output_at_scale", "other"},
    "severity_guess": {"low", "medium", "high"},
    "meets_fmir_definition": {"yes", "no", "ambiguous"},
    "would_meet_72h": {"yes", "no", "unknown"},
    "second_coder_agrees": {"yes", "no", "not_coded"},
}
REQUIRED = ["event_id", "title", "date_disclosed", "developer", "category",
            "meets_fmir_definition", "fmir_rationale", "source_urls", "coder"]


def load(path):
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def validate(rows):
    errors = []
    seen = set()
    for i, r in enumerate(rows, start=2):
        eid = r.get("event_id", "")
        if eid in seen:
            errors.append(f"line {i}: duplicate event_id {eid}")
        seen.add(eid)
        for k in REQUIRED:
            if not (r.get(k) or "").strip():
                errors.append(f"line {i} ({eid}): missing {k}")
        for k, allowed in ENUMS.items():
            v = (r.get(k) or "").strip()
            if v and v not in allowed:
                errors.append(f"line {i} ({eid}): {k}={v!r} not in {sorted(allowed)}")
        if not any(u.strip().startswith("http") for u in (r.get("source_urls") or "").split(";")):
            errors.append(f"line {i} ({eid}): needs at least one public source URL")
    return errors


def summarise(rows):
    print(f"{len(rows)} events")
    for k in ["category", "meets_fmir_definition", "would_meet_72h", "disclosed_by"]:
        print(f"\n{k}:")
        for v, n in Counter(r.get(k, "") or "(blank)" for r in rows).most_common():
            print(f"  {v:28} {n}")
    coded = [r for r in rows if r.get("second_coder_agrees") in ("yes", "no")]
    if coded:
        agree = sum(r["second_coder_agrees"] == "yes" for r in coded)
        print(f"\nInter-coder agreement: {agree}/{len(coded)}")


if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else HERE / "data.csv"
    rows = load(path)
    errs = validate(rows)
    for e in errs:
        print("ERROR", e)
    summarise(rows)
    sys.exit(1 if errs else 0)
